it('accepts a list_sessions frame with its optional limit and before cursor, drops any client userId, and names the field it refuses', () => {
  const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
  const goodFrames = [
    {frame: {type: 'list_sessions'}, data: {type: 'list_sessions'}},
    {frame: {type: 'list_sessions', limit: 0}, data: {type: 'list_sessions', limit: 0}},
    {
      frame: {type: 'list_sessions', limit: 10, before, userId: 'u2'},
      data: {type: 'list_sessions', limit: 10, before},
    },
    {
      frame: {type: 'list_sessions', before: {updatedAt: 1735689600000, sessionId: 's3'}},
      data: {type: 'list_sessions', before: {updatedAt: 1735689600000, sessionId: 's3'}},
    },
  ];
  const badFrames = [
    {type: 'list_sessions', limit: 'ten'},
    {type: 'list_sessions', limit: -1},
    {type: 'list_sessions', limit: 1.5},
    {type: 'list_sessions', before: 'not-an-object'},
    {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
    {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
    {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
    {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
  ];

  expect({
    accepted: goodFrames.map(({frame}) => validateMessage(frame)),
    refused: badFrames.map(frame => validateMessage(frame)),
  }).toEqual({
    accepted: goodFrames.map(({data}) => ({valid: true, data})),
    refused: badFrames.map(() => ({valid: false, error: expect.stringMatching(/\b(limit|before)\b/)})),
  });
});

